pub mod style {
    pub const BOLD: u8 = 1;
    pub const ITALIC: u8 = 2;
    pub const MONO: u8 = 4;
    pub const SUB: u8 = 8;
    pub const SUP: u8 = 16;
    pub const UNDERLINE: u8 = 32;
}

// Approximate divisor for CSS font-size="smaller".
const SMALLER: f64 = 1.2;

pub trait TextMeasurer {
    fn width(&self, text: &str, size: f64, style: u8) -> f64;
}

// Advance widths of printable ASCII in thousandths of an em, two base-36 digits each.
// Generated by Pele's scripts/gen-metrics.mjs from Arial.
const REGULAR: &str = "7q7q9vfgfgopij5b9999atg87q997q7qfgfgfgfgfgfgfgfgfgfg7q7qg8g8g8fgs7ijijk2k2ijgzlmk27qdwijfgn5k2lmijlmk2ijgzk2ijq8ijijgz7q7q7qd1fg99fgfgdwfgfg7qfgfg6666dw66n5fgfgfgfg99dw7qfgdwk2dwdwdw9a789ag8";
const BOLD: &str = "7q99d6fgfgopk26m9999atg87q997q7qfgfgfgfgfgfgfgfgfgfg9999g8g8g8gzr3k2k2k2k2ijgzlmk27qfgk2gzn5k2lmijlmk2ijgzk2ijq8ijijgz997q99g8fg99fggzfggzfg99gzgz7q7qfg7qopgzgzgzgzatfg99gzfglmfgfgdwat7satg8";

const fn digit(b: u8) -> u16 {
    if b <= b'9' {
        (b - b'0') as u16
    } else {
        (b - b'a') as u16 + 10
    }
}

const fn unpack(packed: &str) -> [u16; 95] {
    let bytes = packed.as_bytes();
    let mut out = [0u16; 95];
    let mut i = 0;
    while i < 95 {
        out[i] = digit(bytes[i * 2]) * 36 + digit(bytes[i * 2 + 1]);
        i += 1;
    }
    out
}

static REGULAR_TABLE: [u16; 95] = unpack(REGULAR);
static BOLD_TABLE: [u16; 95] = unpack(BOLD);

fn is_wide(c: u32) -> bool {
    (0x1100..=0x115f).contains(&c)
        || (0x2e80..=0xa4cf).contains(&c)
        || (0xac00..=0xd7a3).contains(&c)
        || (0xf900..=0xfaff).contains(&c)
        || (0xfe30..=0xfe4f).contains(&c)
        || (0xff00..=0xff60).contains(&c)
        || (0xffe0..=0xffe6).contains(&c)
        // Outside the basic plane: Pele counts the leading surrogate as wide and the trailing one as nothing.
        || c >= 0x10000
}

fn is_zero_width(c: u32) -> bool {
    c == 0xad || (0x300..=0x36f).contains(&c) || (0x200b..=0x200f).contains(&c) || (0xfe00..=0xfe0f).contains(&c) || c == 0xfeff
}

// Estimates widths from a table of Arial advances.
pub struct MetricsMeasurer;

impl TextMeasurer for MetricsMeasurer {
    fn width(&self, text: &str, size: f64, style: u8) -> f64 {
        let mono = style & style::MONO != 0;
        let eff = if style & (style::SUB | style::SUP) != 0 { size / SMALLER } else { size };
        let table = if style & style::BOLD != 0 { &BOLD_TABLE } else { &REGULAR_TABLE };
        let mut units: u64 = 0;
        for ch in text.chars() {
            let c = ch as u32;
            if c < 32 {
                continue;
            }
            if c < 127 {
                units += if mono { 600 } else { table[(c - 32) as usize] as u64 };
            } else if is_zero_width(c) {
                continue;
            } else if is_wide(c) {
                units += if mono { 1200 } else { 1000 };
            } else {
                units += if mono { 600 } else { 580 };
            }
        }
        (units as f64 * eff) / 1000.0
    }
}

// Scales the built-in metrics, for a host font that runs wider or narrower than Arial.
pub struct ScaledMeasurer(pub f64);

impl TextMeasurer for ScaledMeasurer {
    fn width(&self, text: &str, size: f64, style: u8) -> f64 {
        MetricsMeasurer.width(text, size, style) * self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn arial_widths() {
        // 'A' is 667 units and ' ' 278 in Arial.
        assert_eq!(MetricsMeasurer.width("A", 1000.0, 0), 667.0);
        assert_eq!(MetricsMeasurer.width(" ", 1000.0, 0), 278.0);
        assert_eq!(MetricsMeasurer.width("ab", 10.0, style::MONO), 12.0);
    }
}
